from abc import ABC, abstractmethod

# Interfaces pequeñas y específicas (cumple ISP)
class Workable(ABC):
    @abstractmethod
    def work(self):
        pass


class Eatable(ABC):
    @abstractmethod
    def eat(self):
        pass


class Sleepable(ABC):
    @abstractmethod
    def sleep(self):
        pass


class Human(Workable, Eatable, Sleepable):
    '''Cumple ISP: implementa solo las interfaces que necesita'''

    def work(self):
        return 'Human working'

    def eat(self):
        return 'Human eating'

    def sleep(self):
        return 'Human sleeping'


class Robot(Workable):
    '''Cumple ISP: solo implementa Workable, no Eatable ni Sleepable'''

    def work(self):
        return 'Robot working'

    # Robot NO tiene eat() ni sleep() porque no los necesita
    # No está forzado a implementarlos


# Uso:
def make_work(worker: Workable):
    '''Función que acepta cualquier Workable'''
    return worker.work()


def make_eat(entity: Eatable):
    '''Función que acepta cualquier Eatable'''
    return entity.eat()


def make_sleep(entity: Sleepable):
    '''Función que acepta cualquier Sleepable'''
    return entity.sleep()


# Uso:
print(make_work(Human()))   # 'Human working'
print(make_work(Robot()))   # 'Robot working'

print(make_eat(Human()))    # 'Human eating'
# print(make_eat(Robot()))  # ✗ Error de tipo (correcto: Robot no es Eatable)

print(make_sleep(Human()))  # 'Human sleeping'
# print(make_sleep(Robot())) # ✗ Error de tipo (correcto: Robot no es Sleepable)

# LSP cumplido: cada clase implementa solo las interfaces que necesita
# ISP cumplido: Robot no está forzado a implementar eat() ni sleep()

