from abc import ABC, abstractmethod
from typing import List, Protocol, runtime_checkable

# ========================================================================
#  ISP: INTERFACE SEGREGATION PRINCIPLE
# ========================================================================
# "Clients should not be forced to depend on interfaces they do not use"
# - Robert C. Martin
#
# INTERFAZ GRANDE (GOD INTERFACE):
#   - Obliga a implementar métodos que no se necesitan
#   - Cambios en la interfaz afectan a TODAS las implementaciones
#   - Dificulta agregar nuevos tipos (deben implementar TODO)
#
# INTERFACES PEQUEÑAS (SEGREGATED):
#   - Cada cliente implementa solo lo que necesita
#   - Cambios en una interfaz solo afectan a quienes la usan
#   - Fácil agregar nuevos tipos (implementan solo lo relevante)

# ========================================================================
#  EJEMPLO 1: SISTEMA DE DOCUMENTOS
# ========================================================================

# ANTES: interfaz grande (viola ISP)
class DocumentProcessor(ABC):
    '''Interfaz grande: obliga a implementar TODO'''

    @abstractmethod
    def read(self):
        pass

    @abstractmethod
    def write(self):
        pass

    @abstractmethod
    def print_document(self):
        pass

    @abstractmethod
    def fax(self):
        pass


class ModernPrinter(DocumentProcessor):
    '''Implementa todo: OK'''

    def read(self):
        return 'Reading'

    def write(self):
        return 'Writing'

    def print_document(self):
        return 'Printing'

    def fax(self):
        return 'Faxing'


class SimpleReader(DocumentProcessor):
    '''VIOLA ISP: solo necesita read(), pero forzado a implementar todo'''

    def read(self):
        return 'Reading'

    def write(self):
        raise NotImplementedError('SimpleReader cannot write')

    def print_document(self):
        raise NotImplementedError('SimpleReader cannot print')

    def fax(self):
        raise NotImplementedError('SimpleReader cannot fax')


# DESPUÉS: interfaces segregadas (cumple ISP)
@runtime_checkable
class Readable(Protocol):
    def read(self) -> str:
        ...


@runtime_checkable
class Writable(Protocol):
    def write(self, content: str) -> None:
        ...


@runtime_checkable
class Printable(Protocol):
    def print_document(self) -> str:
        ...


@runtime_checkable
class Faxable(Protocol):
    def fax(self) -> str:
        ...


class ModernPrinterFixed(Readable, Writable, Printable, Faxable):
    '''Implementa todas las interfaces que necesita'''

    def read(self):
        return 'Reading'

    def write(self, content):
        pass

    def print_document(self):
        return 'Printing'

    def fax(self):
        return 'Faxing'


class SimpleReaderFixed(Readable):
    '''Cumple ISP: solo implementa Readable'''

    def read(self):
        return 'Reading'

    # NO tiene write(), print_document(), ni fax()
    # No está forzada a implementarlos


# Funciones que aceptan interfaces específicas
def process_readable(doc: Readable):
    return doc.read()


def process_writable(doc: Writable, content: str):
    doc.write(content)


def process_printable(doc: Printable):
    return doc.print_document()


# Uso:
print(process_readable(SimpleReaderFixed()))   # 'Reading'
print(process_printable(ModernPrinterFixed())) # 'Printing'

# process_printable(SimpleReaderFixed())  # ✗ Error de tipo (correcto)
# SimpleReaderFixed no es Printable, no está forzada a implementar print


# ========================================================================
#  EJEMPLO 2: SISTEMA DE NOTIFICACIONES
# ========================================================================

# ANTES: interfaz grande
class NotificationService(ABC):
    @abstractmethod
    def send_email(self, to, subject, body):
        pass

    @abstractmethod
    def send_sms(self, to, message):
        pass

    @abstractmethod
    def send_push(self, device_id, message):
        pass

    @abstractmethod
    def send_webhook(self, url, payload):
        pass


class EmailOnlyService(NotificationService):
    '''VIOLA ISP: solo necesita send_email'''

    def send_email(self, to, subject, body):
        return f'Email to {to}'

    def send_sms(self, to, message):
        raise NotImplementedError

    def send_push(self, device_id, message):
        raise NotImplementedError

    def send_webhook(self, url, payload):
        raise NotImplementedError


# DESPUÉS: interfaces segregadas
class EmailSender(ABC):
    @abstractmethod
    def send_email(self, to, subject, body):
        pass


class SMSSender(ABC):
    @abstractmethod
    def send_sms(self, to, message):
        pass


class PushSender(ABC):
    @abstractmethod
    def send_push(self, device_id, message):
        pass


class WebhookSender(ABC):
    @abstractmethod
    def send_webhook(self, url, payload):
        pass


class EmailOnlyServiceFixed(EmailSender):
    '''Cumple ISP: solo implementa EmailSender'''

    def send_email(self, to, subject, body):
        return f'Email to {to}'


class FullNotificationService(EmailSender, SMSSender, PushSender, WebhookSender):
    '''Implementa todas las interfaces'''

    def send_email(self, to, subject, body):
        return f'Email to {to}'

    def send_sms(self, to, message):
        return f'SMS to {to}'

    def send_push(self, device_id, message):
        return f'Push to {device_id}'

    def send_webhook(self, url, payload):
        return f'Webhook to {url}'


# Funciones que aceptan interfaces específicas
def notify_by_email(sender: EmailSender, to, subject, body):
    return sender.send_email(to, subject, body)


def notify_by_sms(sender: SMSSender, to, message):
    return sender.send_sms(to, message)


# Uso:
print(notify_by_email(EmailOnlyServiceFixed(), 'user@example.com', 'Hello', 'Hi'))
# notify_by_sms(EmailOnlyServiceFixed(), 'user', 'Hi')  # ✗ Error de tipo (correcto)

print(notify_by_email(FullNotificationService(), 'user@example.com', 'Hello', 'Hi'))
print(notify_by_sms(FullNotificationService(), '+1234567890', 'Hi'))


# ========================================================================
#  ISP CON PROTOCOLS (DUCK TYPING ESTATICO)
# ========================================================================
# Python 3.8+ tiene typing.Protocol para interfaces estructurales
# No necesitas heredar de la interfaz, solo implementar los métodos

@runtime_checkable
class Swimmable(Protocol):
    def swim(self) -> str:
        ...


class Duck:
    '''No hereda de Swimmable, pero implementa swim()'''

    def swim(self):
        return 'Duck swimming'


class Fish:
    '''No hereda de Swimmable, pero implementa swim()'''

    def swim(self):
        return 'Fish swimming'


def make_swim(entity: Swimmable):
    '''Acepta cualquier objeto con método swim()'''
    return entity.swim()


print(make_swim(Duck()))   # 'Duck swimming'
print(make_swim(Fish()))   # 'Fish swimming'

# Duck y Fish no heredan de Swimmable, pero son Swimmable
# porque implementan el método swim()
# Esto es duck typing estático: "si nada como pato, es un pato"


# ========================================================================
#  CUÁNDO APLICAR ISP
# ========================================================================
# APLICA ISP cuando:
#   - Una interfaz tiene más de 5-7 métodos
#   - Implementaciones tienen métodos vacíos o con raise NotImplementedError
#   - Diferentes clientes usan diferentes subconjuntos de la interfaz
#   - Cambios en la interfaz afectan implementaciones que no usan esos métodos
#
# NO APLIQUES ISP cuando:
#   - La interfaz es pequeña (2-3 métodos) y todas las implementaciones la usan completa
#   - Dividir crearía más complejidad de la que resuelve
#   - Todos los clientes realmente usan todos los métodos
#
# REGLA PRÁCTICA:
#   Si una implementación tiene métodos vacíos o con raise NotImplementedError,
#   es señal de que la interfaz es demasiado grande. Aplica ISP.

# ========================================================================
#  RELACIÓN ISP CON OTROS PRINCIPIOS
# ========================================================================
# ISP y LSP se refuerzan:
#   - LSP dice: subclases deben ser sustituibles por su base
#   - ISP dice: no fuerces implementaciones que no se necesitan
#   - Juntos: cada clase implementa solo lo que puede hacer
#
# ISP y SRP se refuerzan:
#   - SRP dice: una clase, una razón para cambiar
#   - ISP dice: una interfaz, un conjunto cohesivo de métodos
#   - Juntos: interfaces pequeñas con métodos relacionados
#
# ISP y DIP se refuerzan:
#   - DIP dice: depende de abstracciones, no de concreciones
#   - ISP dice: depende solo de las abstracciones que necesitas
#   - Juntos: dependencias mínimas y específicas

# ========================================================================
#  ANTI-PATRÓN: INTERFAZ POR CADA MÉTODO
# ========================================================================
# MAL: crear una interfaz por cada método (over-segregation)
# class Readable(ABC):
#     @abstractmethod
#     def read(self): ...
#
# class Writable(ABC):
#     @abstractmethod
#     def write(self): ...
#
# class Printable(ABC):
#     @abstractmethod
#     def print(self): ...
#
# class Faxable(ABC):
#     @abstractmethod
#     def fax(self): ...
#
# Esto es over-engineering si siempre se usan juntos.

# BIEN: agrupar por rol/cohesión
# class ReadWriteInterface(Readable, Writable):
#     pass
#
# class OutputInterface(Printable, Faxable):
#     pass
#
# Agrupa interfaces relacionadas, no las segregues en exceso.

